package com.dvopenlabs.freedom.remote;

/** Served locally with the existing PIN/cookie session. No external scripts, fonts or analytics. */
final class PhoneSetupPage {
    static final String HTML="<section id='phoneSetup' hidden><h2>Make this Home yours</h2><p>Enable setup for this session on TV and Phone setup sharing in the launcher. Read the current Home, prepare a draft, then review and Apply on the TV.</p><button id='readSetup'>Read current Home</button><form id='setupForm' hidden><label>Setup name<input id='setupName' maxlength='40' value='My phone setup'></label><label>Home style<select id='look'><option value=''>Keep current</option><option value='clean'>Clean</option><option value='glass'>Glass</option><option value='cinema'>Cinema</option><option value='legacy'>Classic</option></select></label><label>App position<select id='position'><option value=''>Keep current</option><option>top</option><option>middle</option><option>bottom</option></select></label><label>Icon size<select id='iconSize'><option value=''>Keep current</option><option>small</option><option>medium</option><option>large</option></select></label><label>Text size<select id='textSize'><option value=''>Keep current</option><option value='85'>85%</option><option value='100'>100%</option><option value='110'>110%</option><option value='120'>120%</option></select></label><p>Favorite apps: select in the order you want. Leave all unchecked to keep your current order.</p><div id='appChoices'></div><button type='submit'>Send draft for TV review</button></form><h3>Your artwork</h3><p>Send a JPEG/PNG up to 8 MB, or a silent H.264 MP4 up to 48 MB / 60 seconds. On TV open Received from phone to review and import. Upload never replaces wallpaper.</p><label>Wallpaper file<input id='artwork' type='file' accept='image/jpeg,image/png,video/mp4'></label><button id='sendArtwork'>Send for review</button><p id='setupStatus' role='status'></p></section>";
    static final String SCRIPT="let inventory=null,favorites=[];const setupStatus=document.querySelector('#setupStatus');async function setupCall(path,data){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const value=await r.json();if(!r.ok||value.error)throw new Error(value.error||'Not available');return value;}document.querySelector('#readSetup').onclick=async()=>{try{inventory=await setupCall('/setup/inventory',{});favorites=[];const host=document.querySelector('#appChoices');host.replaceChildren();for(const app of inventory.apps){const label=document.createElement('label'),box=document.createElement('input'),name=document.createTextNode(app.name);box.type='checkbox';box.onchange=()=>{favorites=favorites.filter(x=>x!==app.package);if(box.checked)favorites.push(app.package);setupStatus.textContent=favorites.length+' apps selected in order';};label.append(box,name);host.append(label);}document.querySelector('#setupForm').hidden=false;setupStatus.textContent='Ready. Other saved choices stay unchanged.';}catch(e){setupStatus.textContent=e.message;}};document.querySelector('#setupForm').onsubmit=async e=>{e.preventDefault();if(!inventory)return;try{const settings={};for(const field of ['look','position','iconSize','textSize']){const value=document.getElementById(field).value;if(value)settings[field==='look'?'experience':field]=field==='textSize'?Number(value):value;}const draft={schema:1,name:document.querySelector('#setupName').value,settings};if(favorites.length)draft.favorites=favorites;await setupCall('/setup/stage',{profile:inventory.profile,revision:inventory.revision,draft});setupStatus.textContent='Draft ready for two minutes. On TV open Launcher settings → Apps & rows → Review phone setup draft. Nothing has been applied.';}catch(e){setupStatus.textContent=e.message;}};document.querySelector('#sendArtwork').onclick=async()=>{const file=document.querySelector('#artwork').files[0];if(!file)return;const kind={'image/jpeg':'jpg','image/png':'png','video/mp4':'mp4'}[file.type];if(!kind||file.size<12||file.size>(kind==='mp4'?48:8)*1024*1024){setupStatus.textContent='Choose a supported file within the size limit.';return;}const button=document.querySelector('#sendArtwork');button.disabled=true;setupStatus.textContent='Sending… keep this page open';try{const r=await fetch('/setup/upload/'+kind,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file});const value=await r.json();if(!r.ok)throw new Error(value.error||'Transfer unavailable');setupStatus.textContent='Sent. On TV open Wallpaper → Received from phone. Wait for verification, then review. Wallpaper is unchanged.';}catch(e){setupStatus.textContent=e.message;}finally{button.disabled=false;}};";
    static final String STYLE="select{display:block;width:100%;padding:14px;background:#192b3e;color:#fff;border:1px solid #7791aa;border-radius:10px;font:inherit;margin-top:8px}#phoneSetup{margin-top:36px;border-top:1px solid #56718a;padding-top:16px}#appChoices{max-height:320px;overflow:auto}#appChoices label{display:flex;gap:12px;align-items:center;padding:8px}#appChoices input{width:24px;height:24px;margin:0}#phoneSetup p{line-height:1.6;color:#c9d7e5}button:disabled{opacity:.55;cursor:wait}select:focus-visible{outline:3px solid #8ddcf0;outline-offset:3px}";
    private PhoneSetupPage(){}
}
